import * as s from "../core/validation/index.js";
import type { JsonValue, Schema } from "../core/validation/schema.js";
import {
  resultCodeSettlementDisputesActionResultCodeSchema,
  type ResultCodeSettlementDisputesActionResultCode,
} from "./result-code-settlement-disputes-action-result-code.js";
import {
  typeSettlementTransactionsActionTypeSchema,
  type TypeSettlementTransactionsActionType,
} from "./type-settlement-transactions-action-type.js";

/** Information about the Action executed. */
export type ActionSettlementReporting = {
  /** A unique identifier generated by the platform to identify an action. */
  id?: string;
  /** Indicates the specific action taken. */
  type?: TypeSettlementTransactionsActionType;
  /** Time indicating when the object was created in ISO-8601 format. */
  timeCreated?: string;
  /**
   * The result of the action executed. * `SUCCESS` - indicates the action executed successfully. *
   * `DECLINED` - indicates the result of the action was to DECLINE it. This means to consider that
   * payment is not allowed and goods or services should not be provided. For transaction processing
   * this means the payment method declined the transaction. * `PENDING` - indicates the result is
   * not known but a final result will be subsequently provided. When the result is known the value
   * can be updated to a SUCCESS, DECLINED or ERROR code. * `ERROR` - indicates the action was
   * PENDING but when the final result was known, it had erred.
   */
  resultCode?: ResultCodeSettlementDisputesActionResultCode;
  /** The id of the app that was used to create the token. */
  appId?: string;
  /** The name of the app the user gave to the application. */
  appName?: string;
  /** Properties the service sent or accepts beyond those declared. */
  additionalProperties?: Record<string, JsonValue>;
};

const actionSettlementReportingProperties: s.Shape<ActionSettlementReporting> = {
  id: s.optional(s.string()),
  type: s.optional(s.lazy(() => typeSettlementTransactionsActionTypeSchema)),
  timeCreated: s.optional(s.string()),
  resultCode: s.optional(s.lazy(() => resultCodeSettlementDisputesActionResultCodeSchema)),
  appId: s.optional(s.string()),
  appName: s.optional(s.string()),
  _keysMap: {
    timeCreated: "time_created",
    resultCode: "result_code",
    appId: "app_id",
    appName: "app_name",
  },
};

export const actionSettlementReportingInternalSchema: Schema<ActionSettlementReporting> =
  s.object<ActionSettlementReporting>(actionSettlementReportingProperties, {
    additionalProperties: s.json(),
  });

export const actionSettlementReportingSchema: Schema<ActionSettlementReporting> = s.lazySchema(() =>
  s.object<ActionSettlementReporting>(
    {
      ...actionSettlementReportingProperties,
      id: s.optional(s.string().check(s.minLength(1), s.maxLength(50))),
      timeCreated: s.optional(s.string().check(s.minLength(1), s.maxLength(50))),
      appId: s.optional(s.string().check(s.minLength(1), s.maxLength(50))),
      appName: s.optional(s.string().check(s.minLength(1), s.maxLength(50))),
    },
    { additionalProperties: s.json() },
  ),
);
